create or replace function public.assert_change_request_validation() returns trigger language plpgsql security definer set search_path=public as $$ declare v public.validations%rowtype; begin if new.validation_id is null then raise exception 'A completed validation is required before creating a change request.'; end if; select * into v from public.validations where id=new.validation_id; if v.id is null or v.status<>'completed' then raise exception 'Change request validation must be completed.'; end if; if v.workspace_id<>new.workspace_id or v.project_id<>new.project_id then raise exception 'Validation must belong to the same workspace and project as the change request.'; end if; return new; end $$;
drop trigger if exists change_request_requires_validation on public.change_requests; create trigger change_request_requires_validation before insert or update of validation_id,workspace_id,project_id on public.change_requests for each row execute function public.assert_change_request_validation();
create or replace function public.evaluate_change_request_policy(p_change_request uuid) returns setof public.policy_evaluations language plpgsql security definer set search_path=public as $$ declare c public.change_requests%rowtype; v public.validations%rowtype; begin select * into c from public.change_requests where id=p_change_request; if c.id is null or not public.is_workspace_member(c.workspace_id) then raise exception 'Change request not accessible'; end if; select * into v from public.validations where id=c.validation_id and status='completed'; if v.id is null then raise exception 'Completed validation required'; end if; delete from public.policy_evaluations where change_request_id=c.id; insert into public.policy_evaluations(workspace_id,project_id,change_request_id,validation_id,policy_key,result,evidence) values (c.workspace_id,c.project_id,c.id,v.id,'validation.completed','pass',jsonb_build_object('validation_id',v.id,'completed_at',v.completed_at)),(c.workspace_id,c.project_id,c.id,v.id,'findings.no_critical',case when coalesce(v.critical_count,0)>0 then 'fail' else 'pass' end,jsonb_build_object('critical_count',coalesce(v.critical_count,0),'required',0)),(c.workspace_id,c.project_id,c.id,v.id,'risk.score',case when coalesce(v.risk_score,100)>=70 then 'fail' when coalesce(v.risk_score,100)>=40 then 'warn' else 'pass' end,jsonb_build_object('risk_score',v.risk_score,'fail_threshold',70,'warn_threshold',40)),(c.workspace_id,c.project_id,c.id,v.id,'findings.high',case when coalesce(v.high_count,0)>0 then 'warn' else 'pass' end,jsonb_build_object('high_count',coalesce(v.high_count,0))); return query select * from public.policy_evaluations where change_request_id=c.id order by created_at; end $$;
revoke all on function public.evaluate_change_request_policy(uuid) from public,anon; grant execute on function public.evaluate_change_request_policy(uuid) to authenticated;
create or replace function public.evaluate_change_request_policy_trigger() returns trigger language plpgsql security definer set search_path=public as $$ begin perform public.evaluate_change_request_policy(new.id); return new; end $$;
drop trigger if exists evaluate_change_request_policy_after_write on public.change_requests; create trigger evaluate_change_request_policy_after_write after insert or update of validation_id on public.change_requests for each row execute function public.evaluate_change_request_policy_trigger();
